import React, { useEffect, useState } from "react";
import axios from "axios";
import "../styles/main.css";

export default function Home() {
  const [data, setData] = useState(null);

  useEffect(() => {
    axios
      .get("http://localhost:5000/api/home")
      .then((res) => setData(res.data))
      .catch((err) => console.error("Error fetching home data:", err));
  }, []);

  if (!data) return <p>Loading...</p>;

  // Convert \u003C ... \u003E escaped HTML to actual HTML
  const decodedWelcome = data.welcomeText
    ? data.welcomeText
        .replace(/\\u003C/g, "<")
        .replace(/\\u003E/g, ">")
        .replace(/\\"/g, '"')
    : "";

  return (
    <main className="home-container">
      {/* === Banner Video === */}
      {data.bannerVideos?.length > 0 && (
        <div className="banner-section">
          <video
            src={`http://localhost:5000${data.bannerVideos[0]}`}
            controls
            autoPlay
            loop
            muted
            className="banner-video"
          />
        </div>
      )}

      {/* === Welcome + Activities === */}
      <section className="welcome-activities card">
        <div className="welcome-left">
          <div
            className="welcome-text"
            dangerouslySetInnerHTML={{ __html: decodedWelcome }}
          />
        </div>

        <div className="activities-right">
          <h3>Our Activities</h3>
          <div className="activities-slider">
            {data.activities?.map((img, i) => (
              <img
                key={i}
                src={`http://localhost:5000${img}`}
                alt={`Activity ${i + 1}`}
              />
            ))}
          </div>
        </div>
      </section>

      {/* === Student Testimonials === */}
      <section className="testimonials card">
        <h2>🎓 Student Testimonials</h2>
        {Array.isArray(data.testimonialVideos) &&
        data.testimonialVideos.length > 0 ? (
          <div className="testimonial-grid">
            {data.testimonialVideos.map((vid, i) => (
              <video
                key={i}
                src={`http://localhost:5000${vid}`}
                controls
                className="testimonial-video"
              />
            ))}
          </div>
        ) : (
          <p>No testimonials yet.</p>
        )}
      </section>
    </main>
  );
}
